// About.jsx
import { useEffect, useMemo, useRef, useState } from 'react';
import './styles.css';

const PARAGRAPHS = [
  "I'm Rochelle, a UI/UX designer who creates meaningful digital experiences. I believe great design happens at the intersection of creativity and functionality.",
  "Every pixel serves a purpose and every interaction feels natural. I'm passionate about designing products that people love to use.",
  'My approach combines user research, visual design, and thoughtful interaction to build experiences that truly connect with people.',
];
const QUOTE = "Design is not just how it looks — it's how it works.";

/* ---------- Human-like typing rhythm ---------- */

// Small seeded random so the "human" rhythm is the same on every render
// (no flicker, no hydration mismatch) but still feels uneven.
function seeded(seed) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) >>> 0;
    let t = s;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/* Builds a cumulative timeline: times[i] = ms at which character i appears.
   - every key press has a slightly different delay
   - a short hesitation after commas, a longer one after sentence ends
   - a tiny "thinking" pause at the start of each new word now and then */
function buildTimeline(text, cps) {
  const base = 1000 / cps;
  const rand = seeded(text.length * 997 + text.charCodeAt(0));
  const times = [];
  let t = 0;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const prev = text[i - 1];
    let d = base * (0.55 + rand() * 0.9); // 0.55x – 1.45x jitter

    if (ch === ' ') d *= 0.85;
    if (prev === ',' || prev === ';') d += 130 + rand() * 90;
    else if (prev === '—' || prev === ':') d += 160 + rand() * 80;
    else if (prev === '.' || prev === '!' || prev === '?') d += 300 + rand() * 180;
    else if (prev === ' ' && rand() < 0.07) d += 90 + rand() * 120; // brief think

    t += d;
    times.push(t);
  }
  return times;
}

/* Time-based (one rAF loop, not one timer per letter), so it stays smooth
   even when the browser is busy. Calls onDone once when finished. */
function useTypewriter(text, active, cps, onDone) {
  const [count, setCount] = useState(0);
  const doneRef = useRef(onDone);
  doneRef.current = onDone;
  const times = useMemo(() => buildTimeline(text, cps), [text, cps]);

  useEffect(() => {
    if (!active) return;

    const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduce) {
      setCount(text.length);
      doneRef.current?.();
      return;
    }

    let raf;
    let start;
    let shown = 0;
    const tick = (now) => {
      if (start === undefined) start = now;
      const elapsed = now - start;
      while (shown < times.length && times[shown] <= elapsed) shown++;
      setCount((c) => (c === shown ? c : shown));
      if (shown < text.length) raf = requestAnimationFrame(tick);
      else doneRef.current?.();
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [active, text, times]);

  return count;
}

/* The not-yet-typed part stays in the layout (just invisible), so the
   text never jumps or re-wraps while it types.
   The caret shows while typing; `keepCaret` leaves it blinking at the end. */
function TypedText({ text, active, onDone, cps = 34, keepCaret = false }) {
  const count = useTypewriter(text, active, cps, onDone);
  const typing = active && count < text.length;
  const finished = active && count >= text.length;
  const showCaret = typing || (finished && keepCaret);
  return (
    <>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true">
        {text.slice(0, count)}
        {showCaret && <span className={`type-caret ${typing ? 'is-typing' : 'is-idle'}`} />}
        <span className="typed-rest">{text.slice(count)}</span>
      </span>
    </>
  );
}

export default function About() {
  const [headIn, setHeadIn] = useState(false);
  const [step, setStep] = useState(-1); // which line is typing: 0-2 paragraphs, 3 quote

  useEffect(() => {
    const raf = requestAnimationFrame(() => setHeadIn(true));
    const timer = setTimeout(() => setStep(0), 650);
    return () => {
      cancelAnimationFrame(raf);
      clearTimeout(timer);
    };
  }, []);

  // Short pause between lines, like a person finishing one thought
  // and starting the next.
  const next = (i) => () => {
    setTimeout(() => setStep((s) => Math.max(s, i + 1)), 450);
  };

  return (
    <section className="about-section">
      <div className="about-container">
        <div className="about-content">
          <div className={`section-tag reveal-right ${headIn ? 'is-in' : ''}`}>About Me</div>
          <h2 className={`section-title reveal-right ${headIn ? 'is-in' : ''}`} style={{ transitionDelay: '0.12s' }}>
            Crafting <span className="highlight">Digital</span> Experiences
          </h2>

          <div className="about-text">
            {PARAGRAPHS.map((para, i) => (
              <p key={i} className={`about-paragraph reveal-right ${step >= i ? 'is-in' : ''}`}>
                <TypedText text={para} active={step >= i} onDone={next(i)} />
              </p>
            ))}
          </div>

          <div className={`about-highlight reveal-right ${step >= 3 ? 'is-in' : ''}`}>
            <span className="highlight-emoji">✨</span>
            <span className="highlight-text">
              <TypedText text={QUOTE} active={step >= 3} cps={30} keepCaret />
            </span>
          </div>
        </div>
      </div>
    </section>
  );
}
